"""Readable evidence text for rough cut v3, composited in post (never generated by a model).

- register_layers(): the open evidence register in E3. The text is laid on the actual ruled
  lines of the page (found in the frame) through a page-to-frame perspective.
- tag_frames(): EXHIBIT 47 on the red tag in E2, moved with the tag by the per-frame
  homographies from track_plane.py (../overlays/<clip>.track.json).
- OSD and clock helpers for ffmpeg drawtext (body cams, CCTV, the old AX-118 unit, archive).

Needs numpy and Pillow only."""
import datetime, json, os
import numpy as np
from PIL import Image, ImageDraw, ImageFilter, ImageFont

FONTS = '/usr/share/fonts/truetype/'
TYPE = FONTS + 'freefont/FreeMono.ttf'            # typed register entries
TYPE_B = FONTS + 'freefont/FreeMonoBold.ttf'
SANS_B = FONTS + 'dejavu/DejaVuSansCondensed-Bold.ttf'
if not os.path.exists(SANS_B):
    SANS_B = FONTS + 'liberation/LiberationSans-Bold.ttf'
MONO = FONTS + 'dejavu/DejaVuSansMono.ttf'

# one device chain the viewer can follow: register row 47 = tag = FEED 13 = the 13th's camera
SERIAL = 'AX-118-0412'
CASE_OLD = 'NORTHGATE INCIDENT'
DATE_OLD = '09 FEB 2023'


def homography(src, dst):
    """3x3 matrix mapping the four src points onto the four dst points."""
    A, b = [], []
    for (x, y), (u, v) in zip(src, dst):
        A += [[x, y, 1, 0, 0, 0, -u * x, -u * y], [0, 0, 0, x, y, 1, -v * x, -v * y]]
        b += [u, v]
    h = np.linalg.solve(np.array(A, float), np.array(b, float))
    return np.append(h, 1).reshape(3, 3)


def warp(layer, Hm, size):
    """Warp an RGBA layer with Hm (layer -> output) into an output canvas of size (W, H)."""
    inv = np.linalg.inv(Hm)
    inv = inv / inv[2, 2]
    return layer.transform(size, Image.PERSPECTIVE, tuple(inv.flatten()[:8]), Image.BICUBIC)


def apply(Hm, pts):
    p = np.c_[np.asarray(pts, float), np.ones(len(pts))] @ Hm.T
    return p[:, :2] / p[:, 2:]


def worn(layer, amount, seed):
    """Break up the ink a little so it reads as printed or stamped, not as a graphic."""
    a = np.asarray(layer.split()[3], float)
    rng = np.random.default_rng(seed)
    n = Image.fromarray((rng.random(a.shape) * 255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(1.2))
    n = np.asarray(n, float) / 255
    a = a * np.clip(1 - amount + amount * 1.6 * n, 0, 1)
    out = layer.copy()
    out.putalpha(Image.fromarray(a.astype(np.uint8)))
    return out.filter(ImageFilter.GaussianBlur(0.5))


# ---------------------------------------------------------------- register (E3)
# page corners in the rough-cut frame (1280x720), measured on 18_E3_register__sdfast at 1.0 s
LEFT_PAGE = [(318, 89), (645, 83), (640, 621), (211, 627)]
RIGHT_PAGE = [(770, 82), (1103, 79), (1212, 625), (737, 621)]
FLAT = (700, 1000)


def ruled_lines(frame, page, x_frac=0.55):
    """Flat-space y of the printed lines: dark minima down one column of the page."""
    Hf = homography([(0, 0), (FLAT[0], 0), FLAT, (0, FLAT[1])], page)
    g = np.asarray(frame.convert('L'), float)
    ys = []
    for fy in range(40, FLAT[1] - 30, 2):
        x, y = apply(Hf, [(FLAT[0] * x_frac, fy)])[0]
        ys.append((fy, g[int(round(y)), int(round(x))]))
    v = np.array([b for _, b in ys])
    base = np.convolve(v, np.ones(9) / 9, 'same')
    lines, last = [], -99
    for i in range(2, len(v) - 2):
        if v[i] < base[i] - 12 and v[i] == v[i - 2:i + 3].min() and ys[i][0] - last > 18:
            lines.append(ys[i][0]); last = ys[i][0]
    return lines


def register_layers(frame, W, H):
    """(text, stamp) RGBA layers for the register frame. frame: PIL image of the shot."""
    ink = (34, 36, 58, 215)
    out = []
    for page, entries in ((LEFT_PAGE, [
            (0, CASE_OLD, TYPE_B, 40), (1, DATE_OLD + '   CASE 23-0209', TYPE_B, 30),
            (2, 'EVIDENCE REGISTER', TYPE, 30),
            (4, '39  GLOVE, BLACK (L)', TYPE, 27), (5, '40  FLASHLIGHT, CRACKED', TYPE, 27),
            (6, '41  SWABS, SET A', TYPE, 27), (7, '42  SWABS, SET B', TYPE, 27),
            (8, '43  PHOTOGRAPHS 1-88', TYPE, 27), (9, '44  MAGAZINE, 9MM, EMPTY', TYPE, 27)]),
            (RIGHT_PAGE, [
            (0, '45  SHELL CASINGS 9MM (x9)', TYPE, 30), (2, '46  HANDGUN, AT SCENE', TYPE, 30),
            (5, '47  BODY CAMERA 7-12', TYPE_B, 46), (7, '    S/N ' + SERIAL, TYPE_B, 34),
            (8, '    D. REYES', TYPE, 30)])):
        lines = ruled_lines(frame, page)
        layer = Image.new('RGBA', FLAT, (0, 0, 0, 0))
        d = ImageDraw.Draw(layer)
        for k, text, font, size in entries:
            if k < len(lines):
                f = ImageFont.truetype(font, size)
                d.text((48, lines[k] - 4), text, font=f, fill=ink, anchor='ls')
        Hf = homography([(0, 0), (FLAT[0], 0), FLAT, (0, FLAT[1])], page)
        out.append((warp(worn(layer, 0.25, k), Hf, (W, H)), lines, Hf))
    text = Image.alpha_composite(out[0][0], out[1][0])
    # LOST stamp next to row 47, a little crooked
    lines, Hf = out[1][1], out[1][2]
    st = Image.new('RGBA', FLAT, (0, 0, 0, 0))
    s = Image.new('RGBA', (300, 130), (0, 0, 0, 0))
    sd = ImageDraw.Draw(s)
    red = (196, 28, 24, 230)
    sd.rectangle((6, 6, 293, 123), outline=red, width=9)
    sd.text((150, 68), 'LOST', font=ImageFont.truetype(SANS_B, 92), fill=red, anchor='mm')
    s = s.rotate(-7, expand=True, resample=Image.BICUBIC)
    y = lines[10] if len(lines) > 10 else FLAT[1] * 0.5      # under row 47, clear of the serial
    st.alpha_composite(s, (FLAT[0] - s.width - 30, int(y - s.height * 0.70)))
    stamp = warp(worn(st, 0.45, 7), Hf, (W, H))
    return text, stamp


# ---------------------------------------------------------------- tag (E2)
TAG_FLAT = (300, 540)


def tag_layer():
    layer = Image.new('RGBA', TAG_FLAT, (0, 0, 0, 0))
    d = ImageDraw.Draw(layer)
    ink = (16, 12, 10, 225)
    d.text((150, 168), 'EXHIBIT', font=ImageFont.truetype(SANS_B, 58), fill=ink, anchor='mm')
    d.text((150, 285), '47', font=ImageFont.truetype(SANS_B, 170), fill=ink, anchor='mm')
    for y, t, s in ((385, 'NORTHGATE', 30), (418, DATE_OLD, 27), (458, 'BODY CAM 7-12', 27), (490, 'S/N ' + SERIAL, 23)):
        d.text((150, y), t, font=ImageFont.truetype(TYPE_B, s), fill=ink, anchor='mm')
    d.line((40, 360, 260, 360), fill=ink, width=3)
    return worn(layer, 0.35, 47)


def tag_frames(track_json, W, H):
    """Function frame_index -> RGBA overlay with the tag text where the tag is in that frame."""
    tr = json.load(open(track_json))
    Hf = homography([(0, 0), (TAG_FLAT[0], 0), TAG_FLAT, (0, TAG_FLAT[1])], tr['quad'])
    layer = tag_layer()
    sx, sy = W / tr['size'][0], H / tr['size'][1]
    S = np.diag([sx, sy, 1])

    def at(i):
        Ht = np.array(tr['H'][min(i, len(tr['H']) - 1)]).reshape(3, 3)
        return warp(layer, S @ Ht @ Hf, (W, H))
    return at


# ---------------------------------------------------------------- OSD (ffmpeg drawtext)
def epoch(y, mo, d, h, mi, s):
    return int(datetime.datetime(y, mo, d, h, mi, s, tzinfo=datetime.timezone.utc).timestamp())


def _dt(text, x, y, size, color='white', extra=''):
    return (f"drawtext=fontfile={MONO}:text='{text}':x={x}:y={y}:fontsize={size}:fontcolor={color}"
            f":shadowcolor=black@0.7:shadowx=1:shadowy=1{extra}")


def clock(ep, fmt='%Y-%m-%d %T'):
    return '%{pts\\:gmtime\\:' + str(ep) + '\\:' + fmt + '}'


# what each kind of device looks like, so the source reads without the corner labels
LOOK = {
    'bwc': 'vignette=PI/5',                                                  # Team 7 AX-220: clean, wide, dark corners
    'old': ('scale=iw/2:-2,scale=iw*2:-2,colorbalance=rs=.06:gs=.02:bs=-.07,'   # AX-118: half resolution, amber, grain
            'noise=alls=10:allf=t,vignette=PI/4'),
    'cctv': 'fps=12,fps=24',                                                 # fixed cameras record at 12 fps
}


def osd(kind, H, ep=None, unit='', cam='', alpha=1.0):
    """drawtext chain for one source type. Sizes scale with frame height H."""
    s = max(12, int(H * 0.030)); m = int(H * 0.035)
    a = f'@{alpha}'
    if kind == 'bwc':        # Team 7 body cams now: AX-220, ISO date
        return ','.join([_dt('REC', m + int(s * 1.1), m, s, 'white' + a),
                         _dt('*', m, m - int(s * 0.12), int(s * 1.2), '0xE0281C' + a),
                         _dt(clock(ep), m + int(s * 4.2), m, s, 'white' + a),
                         _dt(f'NPD AX-220  {unit}', m, f'h-{m + s}', s, 'white' + a)])
    if kind == 'old':        # the AX-118 generation: amber text, US date, unit top-right
        amber = '0xE8C860' + a
        return ','.join([_dt(f'AX-118  {unit}', f'w-tw-{m}', m, s, amber),
                         _dt(clock(ep, '%m/%d/%Y %T'), m, f'h-{m + s}', s, amber)])
    if kind == 'cctv':
        return ','.join([_dt(cam, m, m, s, 'white' + a), _dt(clock(ep), f'w-tw-{m}', m, s, 'white' + a)])
    if kind == 'drone':
        return ','.join([_dt('AIR-1  ALT 61M', m, m, s, 'white' + a), _dt(clock(ep, '%T'), f'w-tw-{m}', m, s, 'white' + a)])
    if kind == 'room':      # the interview-room recorder names who is in the room
        ss = int(s * 0.85)
        return ','.join([_dt(cam, m, m, ss, 'white' + a), _dt(clock(ep), f'w-tw-{m}', m, ss, 'white' + a),
                         _dt('SUBJECT  N. KADE (7-12)', m, m + int(ss * 1.5), ss, 'white' + a),
                         _dt('INTERVIEWER  INSP. E. WARD', m, m + int(ss * 3.0), ss, 'white' + a)])
    if kind == 'archive':    # old footage pulled from the file: banner + the old unit OSD
        bs = int(s * 0.95)
        return ','.join([f"drawbox=x=0:y={m - 6}:w=iw:h={bs + 14}:color=black@0.55:t=fill",
                         _dt(f'ARCHIVE  -  {CASE_OLD}  -  {DATE_OLD}', '(w-tw)/2', m, bs, '0xEDE8E0'),
                         osd('old', H, ep, unit)])
    raise ValueError(kind)
